(ed/'request_resolution_matrix.md').write_text('# Resolution matrix\n\n'+ '\n'.join(['| Comment | Request | Status | Location/evidence |','| --- | --- | --- | --- |']+[f"| {x['comment']} | {x['subrequest']} | Implemented and checked | {x['location_and_evidence']} |"for x in rows]))
